def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated background is made of rectangular cells separated by
    # uniform grid lines. Locate the line rows and columns by their repetition.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # Keep regularly spaced separator lines; the gaps between them are output
    # cells. Each cell's ordinary background color is its output value, except
    # where a colored mark on a separator identifies that cell.
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [[v for v in row] for row in grid]

    rr = [row_lines[0]]
    for r in row_lines[1:]:
        if r - rr[-1] > 1:
            rr.append(r)
    cc = [col_lines[0]]
    for c in col_lines[1:]:
        if c - cc[-1] > 1:
            cc.append(c)

    out = []
    for i in range(len(rr)-1):
        row = []
        for j in range(len(cc)-1):
            vals = [grid[r][c]
                    for r in range(rr[i]+1, rr[i+1])
                    for c in range(cc[j]+1, cc[j+1])]
            row.append(max(set(vals), key=vals.count) if vals else 0)
        out.append(row)
    return out
