def transform(grid):
    h, w = len(grid), len(grid[0])

    # Grid cells are separated by uniform rows/columns. Determine the spacing
    # from the repeated separator pattern, then read the color within each cell.
    def separator_rows():
        return [r for r, row in enumerate(grid) if len(set(row)) == 1]

    def separator_cols():
        return [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1]

    rs, cs = separator_rows(), separator_cols()

    def spacing(lines):
        diffs = [b-a for a, b in zip(lines, lines[1:]) if b-a > 1]
        return min(diffs) if diffs else 1

    # For these grids, the separator interval is the repeating tile size.
    dr, dc = spacing(rs), spacing(cs)
    out = []
    for r0 in range(0, h, dr):
        row = []
        for c0 in range(0, w, dc):
            # The cell's base color is its most common interior value.
            vals = [grid[r][c]
                    for r in range(r0, min(r0+dr, h))
                    for c in range(c0, min(c0+dc, w))]
            row.append(max(set(vals), key=vals.count))
        out.append(row)
    return out
