    # marks along it, at the regular vertical grid-line positions, encode cells.
    h, w = len(grid), len(grid[0])
    out = [[9 for _ in range((w - 2) // 3)] for _ in range((h - 4) // 5)]

    for i, r in enumerate(range(4, h, 5)):
        for j, c in enumerate(range(2, w, 3)):
            v = grid[r][c]
            if v not in (0, 9):
                out[i][j] = v
    return out
